if (response.success !== true) errors.push('safe preview API success must be true.');
if (response.dryRun !== true) errors.push('safe preview API dryRun must be true.');
if (response.persisted !== false) errors.push('safe preview API persisted must be false.');
if (response.persistable !== false) errors.push('safe preview API persistable must be false.');
if (String(response.contentId ?? '') !== String(request.contentId ?? '')) errors.push('safe preview contentId mismatch.');
