if (response.sourceFetchExecuted !== true) errors.push('sourceFetchExecuted must be true.');
if (response.sourceVerificationExecuted !== false) errors.push('sourceVerificationExecuted must be false.');
if (!Array.isArray(response.results)) errors.push('results must be an array.');
if (new Set(resultIds).size !== resultIds.length) errors.push('result sourceIds must be unique.');
if (requestedIds.length !== resultIds.length) errors.push('result count must match requested sourceIds.');
for (const requestedId of requestedIds) if (!resultIds.includes(requestedId)) errors.push(`missing result sourceId ${requestedId}`);
